mapper.select:
select mn.*, pp.P_Name as pName, cc.Con_Name as conName from Con_Boq_Change mn left join pre_project pp on mn.P_Id = pp.P_ID left join con_contract cc on mn.Con_Id = cc.Con_Id
and mn.Version = #{params.version}
and mn.Boq_Id = #{params.boqId}
and mn.Boqc_Version like concat('%', #{params.boqcVersion}, '%')
and pp.P_Name like concat('%', #{params.pName}, '%')
and cc.Con_Name like concat('%', #{params.conName}, '%')
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Boqc_Create_Time desc
